# Auto-generated by scripts/blossom_hd_frames.py (its own regen mode) from
# the Fufu-Blossom Codex pet pack (~/.codex/pets/fufu-blossom/spritesheet.webp)
# — do not edit by hand. Same extraction as qinglong_hd_frames, forensically
# pinned to it: per-frame quantize(256, FASTOCTREE) on the 1:1 snapped-bbox
# crop reproduces the shipped qinglong PNGs with 0 differing pixels (the
# "NEAREST-fitted at 3/4" line in the qinglong header is legacy mosaic-port
# flavor text — CONTEXT.md's 1:1 account is the real one). For the macro-loop
# pet card the regen pulls five states (idle/waving/jumping/failed/waiting).
# Ground states share ONE union alpha bbox snapped outward to the 4px art
# grid — exactly 144x144, content fills it edge to edge (every state's feet
# line sits at y=200), which is what lets the card pet sit tight like the
# codefufuai card does. jumping's apex lifts the body to y=3 (a 200px slot,
# i.e. a permanent 56px void above the idle pet), so its frames are
# extracted at _JUMP_SLOT for data completeness but no card beat sheet casts
# it. STATE_MS is the pack's previews/animation-spec.json (rows 0/3/4/5/6;
# identical idle row to the qinglong pack — same series). Overlay states are
# only embedded into a card when its beat sheet casts them (consumers
# decide). Regenerate:
# python3 scripts/blossom_hd_frames.py
import base64  # stdlib only at import time: CI's wall.yml runs gen_acfufu_card without Pillow
import re
from pathlib import Path

BOX = (144, 144)  # the card slot — ground-state shared bbox, content fills it
_JUMP_SLOT = (144, 200)  # jumping's own taller slot (data kept; card beat sheets don't cast it)

STATE_ROWS = {"idle": 0, "waving": 3, "jumping": 4, "failed": 5, "waiting": 6}

STATE_MS = {
    "idle": [280, 110, 110, 140, 140, 320],
    "waving": [140, 140, 140, 280],
    "jumping": [140, 140, 140, 140, 280],
    "failed": [140, 140, 140, 140, 140, 140, 140, 240],
    "waiting": [150, 150, 150, 150, 150, 260],
}

# --- frames: auto block (regen rewrites the dict below) ---
FRAMES = {
    "idle": [
        "",
        "",
        "",
        "",
        "",
        "",
    ],
    "waving": [
        "",
        "",
        "",
        "",
    ],
    "jumping": [
        "",
        "",
        "",
        "",
        "",
    ],
    "failed": [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ],
    "waiting": [
        "",
        "",
        "",
        "",
        "",
        "",
    ],
}
# --- end frames ---

STATES = {k: (STATE_MS[k], FRAMES[k]) for k in STATE_ROWS}

_SPRITE_SLOT = BOX
# header says it too: ground states share one tight box so the pet fills its
# slot edge-to-edge (codefufuai-card look); jumping's apex reaches y=3 in the
# atlas and would need a 200px slot that leaves a permanent 56px void above
# the idle pet — so the card beat sheets don't cast jumping, its frames stay
# extracted here at _JUMP_SLOT for any future use


def _regen(pack=None):
    """Re-extract every state row from the installed pack and splice the
    FRAMES dict between the auto-block markers in place. Ground states share
    ONE union bbox snapped outward to the 4px art grid (144x144, content
    fills it — every state's feet line sits at y=200); jumping keeps its own
    taller box against _JUMP_SLOT."""
    import io

    from PIL import Image

    pack = Path(pack or Path.home() / ".codex/pets/fufu-blossom/spritesheet.webp")
    sheet = Image.open(pack).convert("RGBA")
    cw, ch = sheet.size[0] // 8, sheet.size[1] // 9  # codex v1 atlas: 8x9 cells
    cells_by_state = {}
    for name, row in STATE_ROWS.items():
        n = len(STATE_MS[name])  # frame count == duration count, from the pack spec
        cells_by_state[name] = [sheet.crop((c * cw, row * ch, (c + 1) * cw, (row + 1) * ch))
                                for c in range(n)]

    def _snap(u):
        return (u[0] - u[0] % 4, u[1] - u[1] % 4, u[2] + -u[2] % 4, u[3] + -u[3] % 4)

    def _emit(cells, box4, slot):
        w, h = box4[2] - box4[0], box4[3] - box4[1]
        if w > slot[0] or h > slot[1]:
            raise SystemExit(f"snapped bbox {w}x{h} overflows {slot}")
        ox, oy = (slot[0] - w) // 2, (slot[1] - h) // 2
        out = []
        for cell in cells:
            frame = cell.crop(box4).copy()
            canvas = Image.new("RGBA", slot, (0, 0, 0, 0))
            canvas.paste(frame, (ox, oy))
            buf = io.BytesIO()
            canvas.quantize(256, method=Image.FASTOCTREE).save(buf, "PNG")
            out.append(base64.b64encode(buf.getvalue()).decode())
        return out

    ground = [s for s in STATE_ROWS if s != "jumping"]
    gcells = [c for s in ground for c in cells_by_state[s]]
    gb = [c.getchannel("A").getbbox() for c in gcells]
    gbox = _snap((min(b[0] for b in gb), min(b[1] for b in gb),
                  max(b[2] for b in gb), max(b[3] for b in gb)))
    jb = [c.getchannel("A").getbbox() for c in cells_by_state["jumping"]]
    jbox = _snap((min(b[0] for b in jb), min(b[1] for b in jb),
                  max(b[2] for b in jb), max(b[3] for b in jb)))
    frames = {}
    for name, cells in cells_by_state.items():
        if name == "jumping":
            frames[name] = _emit(cells, jbox, _JUMP_SLOT)
        else:
            frames[name] = _emit(cells, gbox, _SPRITE_SLOT)
    report = ([f"ground bbox {gbox[2]-gbox[0]}x{gbox[3]-gbox[1]} -> slot {_SPRITE_SLOT}",
               f"jump bbox {jbox[2]-jbox[0]}x{jbox[3]-jbox[1]} -> slot {_JUMP_SLOT} (data only)"] +
              [f"{name}: {len(v)}f" for name, v in frames.items()])
    p = Path(__file__).resolve()
    text = p.read_text()
    block = ("FRAMES = {\n"
             + "".join(f'    "{k}": [\n' + "".join(f'        "{b}",\n' for b in v)
                       + "    ],\n" for k, v in frames.items())
             + "}")
    # marker-lookahead splice: base64 has no '}' so .*? stops at the closer
    # either way; the lookahead pins it to the auto block's terminator
    text, n = re.subn(r"FRAMES = \{.*?\n\}(?=\n# --- end frames ---)",
                      lambda _: block, text, count=1, flags=re.S)
    if n != 1:
        raise SystemExit("regen: auto block not found — markers missing?")
    p.write_text(text)
    print(f"regen: {len(frames)} states, pack {pack}")
    for line in report:
        print("  " + line)


if __name__ == "__main__":
    _regen()
